INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('1','a13469d3-772d-424a-9150-c2d7c777269f','user','Hi I need photo and drone in Laval',NULL,NULL,NULL,NULL,NULL,'2026-03-02 15:20:58','2026-03-02 15:20:58');
INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('2','a13469d3-772d-424a-9150-c2d7c777269f','assistant','Bonjour! Je peux certainement vous aider avec la photographie et le drone à Laval.\n\nPour préparer votre demande, pourriez-vous me donner votre nom complet et me dire quand vous aimeriez que la séance soit réalisée?\n\nUne fois que j\'aurai ces détails, je pourrai vous recommander le forfait le plus adapté à vos besoins.','512','74','arcee-ai/trinity-large-preview:free','5340','{\"type\":\"follow_up\",\"field\":\"name\"}','2026-03-02 15:21:03','2026-03-02 15:21:03');
INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('3','a1346911-7604-4f8c-95f3-abd04cd37567','user','hi',NULL,NULL,NULL,NULL,NULL,'2026-03-02 15:28:39','2026-03-02 15:28:39');
INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('4','a1346911-7604-4f8c-95f3-abd04cd37567','assistant','Hi there! I\'m Maccento, your real estate media specialist. I\'d love to help you showcase your property beautifully. \n\nCould you share your full name and let me know which service you\'re interested in? We offer professional photography, cinematic videos, drone footage, virtual staging, and more. Also, where is your property located?\n\nLooking forward to creating stunning visuals for your listing!','502','80','arcee-ai/trinity-large-preview:free','3880','{\"type\":\"follow_up\",\"field\":\"name\"}','2026-03-02 15:28:43','2026-03-02 15:28:43');
INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('5','a1346911-7604-4f8c-95f3-abd04cd37567','user','My name is Ashifur Rahman',NULL,NULL,NULL,NULL,NULL,'2026-03-02 16:18:22','2026-03-02 16:18:22');
INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('6','a1346911-7604-4f8c-95f3-abd04cd37567','assistant','Thank you for sharing your name, Ashifur! I\'m Maccento, your real estate media specialist.\n\nTo help me prepare the perfect package for your property, could you tell me:\n\n1. What service are you most interested in? (photography, video, drone, virtual staging, etc.)\n2. Where is your property located?\n3. When do you need the media ready by?\n\nOnce I have these details, I can recommend the ideal package and get your stunning visuals scheduled!','600','100','arcee-ai/trinity-large-preview:free','9565','{\"type\":\"follow_up\",\"field\":\"contact\"}','2026-03-02 16:18:31','2026-03-02 16:18:31');
