INSERT INTO `messages` (`id`,`conversation_id`,`role`,`content`,`tokens_in`,`tokens_out`,`model`,`latency_ms`,`metadata`,`created_at`,`updated_at`) VALUES ('8','a1346911-7604-4f8c-95f3-abd04cd37567','assistant','Thank you for the details, Ashifur! I\'m Maccento, your real estate media specialist.\n\nBased on your needs for photography, video, and drone footage in Montreal with a March 15th deadline, I recommend our Prestige package at $1,299. This includes:\n\n- Professional HDR photography\n- Cinematic property walkthrough video\n- Drone aerial footage\n- Social media cut\n- Floor plan (coming soon)\n\nThis premium package ensures your property stands out in the competitive Montreal market.\n\nWould you like me to reserve this package for you? I just need your email or phone number to send the booking confirmation.','742','126','arcee-ai/trinity-large-preview:free','11689','{\"type\":\"follow_up\",\"field\":\"contact\"}','2026-03-02 16:21:29','2026-03-02 16:21:29');
